-- The supermarket POS on the centre (ADR-0063, ADR-0064): the store's settings, edge servers and
-- tills, the cashiers' PINs, shifts, sales with lines and tenders, shortfalls and refused documents;
-- the POS_SHORTFALL adjustment reason, the AUTO_POS_SHIFT journal source, the POS_SHIFT source
-- document and the four new account roles. Generated by drizzle-kit, then by hand: the REVOKEs,
-- the tenders' append-only guard and the assistant's movement view with the POS numbers.
CREATE TABLE "pos_cashiers" (
	"user_id" bigint PRIMARY KEY NOT NULL,
	"pin_hash" text NOT NULL,
	"pin_set_at" timestamp with time zone DEFAULT now() NOT NULL,
	"pin_set_by" bigint,
	"status" text DEFAULT 'ACTIVE' NOT NULL,
	"failed_count" integer DEFAULT 0 NOT NULL,
	"locked_until" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "pos_cashiers_status" CHECK ("pos_cashiers"."status" IN ('ACTIVE', 'INACTIVE')),
	CONSTRAINT "pos_cashiers_failed" CHECK ("pos_cashiers"."failed_count" >= 0)
);
